/* @lc app=leetcode id=1348 lang=kotlin */ class TweetCounts(val m: HashMap<String, MutableList<Int>> = HashMap()) { fun recordTweet(tweetName: String, time: Int) { m.getOrPut(tweetName) { mutableListOf() }.add(time) } fun getTweetCountsPerFrequency(freq: String, tweetName: String, startTime: Int, endTime: Int): List<Int> = mapOf("minute" to 60, "hour" to 3600, "day" to 86400)[freq]!!.let { d -> IntArray((endTime - startTime) / d + 1).also { r -> m[tweetName].orEmpty().filter { it in startTime..endTime }.forEach { r[(it - startTime) / d]++ } }.toList() } }